CREATE TABLE services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL, UNIQUE(id,organization_id));
CREATE TABLE tariffs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),service_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency IN ('AMD','RUB','USD')),basis text NOT NULL CHECK(basis IN ('unit','area')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(service_id,organization_id) REFERENCES services(id,organization_id),UNIQUE(id,organization_id));
CREATE TABLE payer_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,payer_user_id uuid NOT NULL REFERENCES users(id),service_id uuid NOT NULL,starts_on date NOT NULL,ends_on date,CHECK(ends_on IS NULL OR ends_on>=starts_on),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id),FOREIGN KEY(service_id,organization_id) REFERENCES services(id,organization_id),UNIQUE(id,organization_id));
ALTER TABLE invoices ADD COLUMN created_by uuid REFERENCES users(id);
ALTER TABLE invoices ADD COLUMN published_by uuid REFERENCES users(id);
ALTER TABLE invoices ADD COLUMN published_at timestamptz;
ALTER TABLE invoices ADD CONSTRAINT invoices_id_org_unique UNIQUE(id,organization_id);
CREATE TABLE charges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,payer_assignment_id uuid NOT NULL,period date NOT NULL,tariff_id uuid NOT NULL,invoice_id uuid NOT NULL UNIQUE,FOREIGN KEY(payer_assignment_id,organization_id) REFERENCES payer_assignments(id,organization_id),FOREIGN KEY(tariff_id,organization_id) REFERENCES tariffs(id,organization_id),FOREIGN KEY(invoice_id,organization_id) REFERENCES invoices(id,organization_id),UNIQUE(payer_assignment_id,period));
CREATE TABLE invoice_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES invoices(id),description text NOT NULL,quantity_hundredths bigint NOT NULL CHECK(quantity_hundredths>0),rate_minor bigint NOT NULL CHECK(rate_minor>0),amount_minor bigint NOT NULL CHECK(amount_minor>0));
CREATE FUNCTION immutable_invoice_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM invoices WHERE id=COALESCE(NEW.invoice_id,OLD.invoice_id) AND status='published') OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM invoices WHERE id=OLD.invoice_id AND status='published')) THEN RAISE EXCEPTION 'Published invoice lines are immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_lines_guard BEFORE INSERT OR UPDATE OR DELETE ON invoice_lines FOR EACH ROW EXECUTE FUNCTION immutable_invoice_line();
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),payer_user_id uuid NOT NULL REFERENCES users(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency IN ('AMD','RUB','USD')),source text NOT NULL CHECK(source IN ('manual_bank','sandbox')),reference text NOT NULL,confirmed_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,source,reference),UNIQUE(id,organization_id));
CREATE TABLE payment_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,payment_id uuid NOT NULL,invoice_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(payment_id,organization_id) REFERENCES payments(id,organization_id),FOREIGN KEY(invoice_id,organization_id) REFERENCES invoices(id,organization_id),UNIQUE(payment_id,invoice_id));
CREATE TABLE adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,invoice_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor<>0),reason text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(invoice_id,organization_id) REFERENCES invoices(id,organization_id));
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ledger entries are append-only'; END $$;
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TRIGGER allocation_immutable BEFORE UPDATE OR DELETE ON payment_allocations FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TRIGGER adjustment_immutable BEFORE UPDATE OR DELETE ON adjustments FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TABLE operation_receipts(actor_id uuid NOT NULL REFERENCES users(id),key uuid NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,key));
